return ['domain'=>'zinn-reseller','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'hi_IN','project-id-version'=>'zinn-reseller','pot-creation-date'=>'2026-10-02T18:00:29+00:00','po-revision-date'=>'2026-10-02T18:00:29+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Reseller Toolkit'=>'Zinn® Reseller Toolkit','https://zinndigital.com/wordpress-plugins/zinn-reseller'=>'https://zinndigital.com/wordpress-plugins/zinn-reseller','Sell Zinn Digital® hosting from your own WordPress site — WordPress, WooCommerce, agency, reseller, cloud and VPS hosting. Search and offer domains from your reseller account, sign your clients straight into their hosting panel, and provision hosting automatically when a WooCommerce order is paid.'=>'अपनी खुद की WordPress साइट से Zinn Digital® होस्टिंग बेचें — WordPress, WooCommerce, एजेंसी, रीसेलर, क्लाउड और VPS होस्टिंग। अपने रीसेलर खाते से डोमेन खोजें और प्रदान करें, अपने ग्राहकों को सीधे उनके होस्टिंग पैनल में साइन इन कराएं, और WooCommerce ऑर्डर का भुगतान होने पर होस्टिंग का स्वचालित रूप से प्रावधान करें।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','The hosting platform answered with status %d.'=>'होस्टिंग प्लेटफ़ॉर्म ने स्थिति %d के साथ उत्तर दिया।','Find your domain name'=>'अपना डोमेन नाम ढूंढें','Search'=>'खोजें','No extensions were checked for that name.'=>'उस नाम के लिए किसी भी एक्सटेंशन की जाँच नहीं की गई थी।','Domain search is unavailable on this site at the moment.'=>'इस साइट पर इस समय डोमेन खोज अनुपलब्ध है।','We could not reach the domain registry just now. Please try again in a moment.'=>'हम अभी डोमेन रजिस्ट्री तक नहीं पहुँच सके। कृपया कुछ देर बाद पुनः प्रयास करें।','The API key is missing or no longer valid. Check it under Zinn Digital® → Reseller Toolkit.'=>'API कुंजी गायब है या अब मान्य नहीं है। इसे Zinn Digital® → Reseller Toolkit के अंतर्गत जांचें।','This API key does not carry the sites.view permission, which